inputSchemaRaw:
{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "phone" : {
      "type" : "string",
      "description" : "User phone number, for example +27812815577"
    },
    "fieldName" : {
      "type" : "string",
      "description" : "Document field name from user config, for example identityDocument"
    },
    "fileUrl" : {
      "type" : "string",
      "description" : "Uploaded file public URL"
    }
  },
  "required" : [ "phone", "fieldName", "fileUrl" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "phone" : {
      "type" : "string",
      "description" : "User phone number, for example +27812815577"
    },
    "fieldName" : {
      "type" : "string",
      "description" : "Document field name from user config, for example identityDocument"
    },
    "originalFileName" : {
      "type" : "string",
      "description" : "Original file name, for example id-card.jpg"
    },
    "mimeType" : {
      "type" : "string",
      "description" : "MIME type, for example image/jpeg or application/pdf"
    }
  },
  "required" : [ "phone", "fieldName", "originalFileName", "mimeType" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "city" : {
      "type" : "string",
      "description" : "Optional city name — case-insensitive substring match against store address. Pass null to skip."
    },
    "storeType" : {
      "type" : "string",
      "enum" : [ "FOOD", "CLOTHING", "SALON", "CAR_WASH", "MOVERS", "TIPS", "LICENSING", "PARTS" ],
      "description" : "Optional store type — one of FOOD, CLOTHING, SALON, CAR_WASH, MOVERS, TIPS, LICENSING, PARTS. Pass null to skip."
    },
    "activeStatus" : {
      "type" : "boolean",
      "description" : "Optional availability filter — true = non-OFFLINE stores only, false = OFFLINE stores only, null = no filter."
    }
  },
  "required" : [ ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "role" : {
      "type" : "string",
      "enum" : [ "CUSTOMER", "STORE_ADMIN", "STORE", "MESSENGER", "MESSENGER_ADMIN", "ADMIN", "AMBASSADOR", "REFERRAL_PARTNER" ],
      "description" : "This will always have a value MESSENGER because this serach is only allow to search drivers available"
    },
    "latitude" : {
      "type" : "number"
    },
    "longitude" : {
      "type" : "number"
    },
    "range" : {
      "type" : "number",
      "description" : "range is in degrees. 1 degree is approximately 111 km. So a range of 0.01 would be approximately 1.11 km"
    },
    "storeType" : {
      "type" : "string",
      "enum" : [ "FOOD", "CLOTHING", "SALON", "CAR_WASH", "MOVERS", "TIPS", "LICENSING", "PARTS" ]
    }
  },
  "required" : [ "role", "latitude", "longitude", "range", "storeType" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "payoutType" : {
      "type" : "string",
      "enum" : [ "SHOP", "MESSENGER", "AMBASSADOR", "REFERRAL_PARTNER" ],
      "description" : "For driver the payoutType is MESSENGER"
    },
    "from" : {
      "type" : "string",
      "description" : "Date time format is like 2026-04-09T00:00:00.000+00:00"
    },
    "toDate" : {
      "type" : "string",
      "description" : "Date time format is like 2026-04-09T00:00:00.000+00:00"
    },
    "toId" : {
      "type" : "string",
      "description" : "This is the Driver/Messenger id to use for lookup"
    }
  },
  "required" : [ "payoutType", "from", "toDate", "toId" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "customerId" : {
      "type" : "string",
      "description" : "The customer's profile ID"
    },
    "customerConfirmed" : {
      "type" : "boolean",
      "description" : "Must be true — agent must have confirmed the customer's intent before placing the order"
    },
    "idempotencyKey" : {
      "type" : "string",
      "description" : "Unique key for this order attempt to prevent duplicate orders"
    },
    "shopId" : {
      "type" : "string",
      "description" : "The store/shop ID to place the order against"
    },
    "description" : {
      "type" : "string",
      "description" : "Brief description of the order"
    },
    "orderType" : {
      "type" : "string",
      "description" : "Order type: ONLINE or INSTORE"
    },
    "basketJson" : {
      "type" : "string",
      "description" : "JSON of the Basket with items array, e.g. {\"items\":[{\"name\":\"chips\",\"quantity\":2,\"price\":10,\"totalPrice\":20}]}"
    },
    "shippingDataJson" : {
      "type" : "string",
      "description" : "JSON of ShippingData (required for ONLINE orders). null for INSTORE orders."
    }
  },
  "required" : [ "customerId", "customerConfirmed", "idempotencyKey", "shopId", "description", "orderType", "basketJson" ],
  "additionalProperties" : false
}
